#root#root .cos-fleet-status-strip>p,#root#root .cos-fleet-status-detail{padding:0 12px 10px;font-size:11px;line-height:1.5;color:#aebed0}
#root#root .cos-fleet-status-detail>details{margin-top:8px}
#root#root .cos-fleet-vision-toggle{margin:10px 0 14px;border:1px solid #30485f;border-radius:9px;background:#0f1d2e}
#root#root .cos-fleet-vision-toggle>summary{min-height:44px;padding:12px 14px;cursor:pointer;font-size:13px;font-weight:700;color:#d7e7ff}
#root#root .cos-fleet-vision-toggle[open]>summary{border-bottom:1px solid #30485f}
#root#root .cos-fleet-vision-toggle .cos-vision-brief{margin:0;border:0;border-radius:0}
@media(max-width:750px){
 #root#root .cos-fleet-status-strip>summary{flex-wrap:wrap;gap:4px 8px}
 #root#root .cos-fleet-status-strip>summary b{margin-left:0;flex-basis:100%}
}

